102	  protected onSitzplanKeydown(event: KeyboardEvent): void {
103	    const plan = this.sitzplan();
104	    const aktuell = this.fokussiertePosition();
105	    if (!plan || !aktuell) return;
106	
107	    switch (event.key) {
108	      case 'ArrowRight':
109	        event.preventDefault();
110	        this.bewegeHorizontal(plan, aktuell, 1);
111	        break;
112	      case 'ArrowLeft':
113	        event.preventDefault();
114	        this.bewegeHorizontal(plan, aktuell, -1);
115	        break;
116	      case 'ArrowDown':
117	        event.preventDefault();
118	        this.bewegeVertikal(plan, aktuell, 1);
119	        break;
120	      case 'ArrowUp':
121	        event.preventDefault();
122	        this.bewegeVertikal(plan, aktuell, -1);
123	        break;
124	      case ' ':
125	      case 'Enter':
126	        event.preventDefault();
127	        this.aktiviereFokussiertePosition(plan, aktuell);
128	        break;
129	    }
130	  }
