132	  private aktiviereFokussiertePosition(plan: Sitzplan, aktuell: Position): void {
133	    const reihe = plan.reihen.find((r) => r.reihe === aktuell.reihe);
134	    const position = reihe?.positionen.find((p) => p.spalte === aktuell.spalte);
135	    if (!position || position.status === 'Belegt' || !position.code) return;
136	    this.auswahlUmschalten(position.code);
137	  }
138	
139	  private bewegeHorizontal(plan: Sitzplan, aktuell: Position, richtung: 1 | -1): void {
140	    const reihe = plan.reihen.find((r) => r.reihe === aktuell.reihe);
141	    if (!reihe) return;
142	    let spalte = aktuell.spalte + richtung;
143	    while (spalte >= 1 && spalte <= reihe.positionen.length) {
144	      const position = reihe.positionen.find((p) => p.spalte === spalte);
145	      if (position?.typ === 'Sitzplatz') {
146	        this.setzeFokus({ reihe: aktuell.reihe, spalte });
147	        return;
148	      }
149	      spalte += richtung;
150	    }
151	  }
152	
153	  private bewegeVertikal(plan: Sitzplan, aktuell: Position, richtung: 1 | -1): void {
154	    const rowIndex = plan.reihen.findIndex((r) => r.reihe === aktuell.reihe);
155	    const naechsterIndex = rowIndex + richtung;
156	    if (naechsterIndex < 0 || naechsterIndex >= plan.reihen.length) return;
157	    const naechsteReihe = plan.reihen[naechsterIndex];
158	    const position = naechsteReihe.positionen.find((p) => p.spalte === aktuell.spalte);
159	    if (!position) return;
160	    this.setzeFokus({ reihe: naechsteReihe.reihe, spalte: aktuell.spalte });
161	  }
162	
163	  private setzeFokus(position: Position): void {
164	    this.fokussiertePosition.set(position);
165	    const code = `${position.reihe}${position.spalte}`;
166	    (
167	      this.sitzplanRef()?.nativeElement.querySelector(`[data-code="${code}"]`) as HTMLElement | null
168	    )?.focus();
169	  }
170	
171	  private ersteSitzplatzPosition(plan: Sitzplan): Position | null {
172	    for (const reihe of plan.reihen) {
173	      const position = reihe.positionen.find((p: SitzplanPosition) => p.typ === 'Sitzplatz');
174	      if (position) return { reihe: reihe.reihe, spalte: position.spalte };
175	    }
176	    return null;
177	  }
178	}
